<?php $msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&checkCsrf($_POST['csrf']??null)){if($_POST['action']==='add'){$pdo->prepare('INSERT INTO lokasi_kampus(nama_lokasi,latitude,longitude,radius,status) VALUES(?,?,?,?,?)')->execute([trim($_POST['nama']),$_POST['lat'],$_POST['lng'],max(10,(int)$_POST['radius']),$_POST['status']]);$msg='Lokasi ditambahkan.';}else{$pdo->prepare('UPDATE lokasi_kampus SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);}}$rows=$pdo->query('SELECT * FROM lokasi_kampus ORDER BY id')->fetchAll();?><section class="section"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="add"><div class="form-grid three"><input class="input" name="nama" placeholder="Nama lokasi" required><input class="input" name="lat" type="number" step="0.00000001" placeholder="Latitude" required><input class="input" name="lng" type="number" step="0.00000001" placeholder="Longitude" required><input class="input" name="radius" type="number" value="100" min="10"><select class="select" name="status"><option>Aktif</option><option>Nonaktif</option></select></div><div class="actions"><button class="btn btn-primary">Tambah lokasi</button></div></form></section><section class="section" style="margin-top:20px"><table class="table"><thead><tr><th>Lokasi</th><th>Koordinat</th><th>Radius</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama_lokasi'])?></td><td><?=e($r['latitude'].', '.$r['longitude'])?></td><td><?=e($r['radius'])?> m</td><td><span class="badge <?= $r['status']==='Aktif'?'green':'red' ?>"><?=e($r['status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="select" onchange="this.form.submit()"><option <?=$r['status']==='Aktif'?'selected':''?>>Aktif</option><option <?=$r['status']==='Nonaktif'?'selected':''?>>Nonaktif</option></select></form></td></tr><?php endforeach;?></tbody></table></section>
